# Let me check horizontal/vertical symmetry for both demos
# Also check if the transformation in demo 1 has a pattern

def is_horizontally_symmetric(grid):
    rows = len(grid)
    cols = len(grid[0])
    for r in range(rows):
        row = grid[r]
        for c in range(cols // 2):
            if row[c] != row[cols - 1 - c]:
                return False
    return True

def is_vertically_symmetric(grid):
    rows = len(grid)
    for r in range(rows // 2):
        if grid[r] != grid[rows - 1 - r]:
            return False
    return True

def is_diagonally_symmetric(grid):
    rows = len(grid)
    cols = len(grid[0])
    # Main diagonal: grid[r][c] == grid[c][r]
    # Only works for square grids
    if rows != cols:
        return check_hypercube_diag(grid)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != grid[c][r]:
                return False
    return True

def check_hypercube_diag(grid):
    # For non-square, wrap indices
    rows = len(grid)
    cols = len(grid[0])
    for r in range(rows):
        for c in range(cols):
            # Map to square bounds
            rr = min(r, cols - 1)
            cc = min(c, rows - 1)
            if grid[r][c] != grid[cc][rr]:
                return False
    return True

