# Now let's look at the transformation in demo 1 more carefully
# What determines which cells change?

# Maybe it's about "holes" in the shape?
# Let me check if demo 1 shape has a hole

def count_holes_in_shape(grid):
    # Find all non-background cells (let's say non-1 in demo1)
    rows = len(grid)
    cols = len(grid[0])
    non_bg = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 1:
                non_bg.append((r, c))

    # Check if the region of non-bg cells contains a "hole" of background
    # A hole is a background cell completely surrounded by non-bg
    import collections
    from collections import deque

    visited = [[False] * cols for _ in range(rows)]

    # First, mark all boundary-adjacent bg cells as "exterior"
    # Then any bg cell not visited is a hole
    bg = 1

    queue = deque()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg:
                visited[r][c] = True
                # Check if this is on boundary
                if r == 0 or r == rows-1 or c == 0 or c == cols-1:
                    queue.append((r, c))

    # BFS to mark all exterior bg cells
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == bg and visited[nr][nc] == False:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    # Count holes
    holes = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg and visited[r][c] == False:
                holes += 1

    return holes

